ription": "Students learn how organizations choose benefits based on workforce needs, market expectations, affordability, and values."}, {"id": "69d88af9-30f1-43d2-a002-8a25ca958bd6", "type": "subtopic", "title": "Health and welfare benefits", "children": [{"id": "0c77ef89-fa83-44df-bc0d-b822ecb9f5c4", "type": "concept", "title": "medical plans"}, {"id": "e8811277-9e6f-48e6-b0ff-ea36d51f93cd", "type": "concept", "title": "dental and vision"}, {"id": "2502a67d-6cb9-47e0-85ac-7e62b8a1c9f6", "type": "concept", "title": "life insurance"}, {"id": "d3549b22-f6eb-4668-91be-1be46a6fa3db", "type": "concept", "title": "disability insurance"}, {"id": "05649e28-1a52-439c-baf1-40709cb8e73b", "type": "concept", "title": "employee assistance programs"}], "description": "The unit introduces health plans and related welfare benefits that dominate benefit budgets."}, {"id": "91a8edfe-d76a-4fdd-9ff5-18e3c51482c5", "type": "subtopic", "title": "Paid time, flexibility, and wellbeing", "children": [{"id": "bca216aa-b087-425c-9ee0-895f47c75454", "type": "concept", "title": "paid time off"}, {"id": "b06d2373-182b-40db-afbb-2642ad0be3b8", "type": "concept", "title": "sick leave"}, {"id": "dc83dec0-c94b-4848-9877-34ef0fd4690d", "type": "concept", "title": "parental leave"}, {"id": "e1f1835a-ef97-4338-b551-3b72a13e3483", "type": "concept", "title": "wellbeing programs"}, {"id": "ff0498b9-17d7-45c4-952c-c0a08a499d40", "type": "concept", "title": "flexible work"}], "description": "Students examine leave, scheduling, flexibility, and wellbeing benefits as part of total rewards."}]}, {"id": "e6ab124f-f4e4-407e-add9-da19f1239742", "type": "topic", "title": "Retirement, Financial Security, and Benefits Finance", "description": "Students learn how retirement and financial-security benefits work, why they matter, and how employers manage long-term cost and compliance obligations.", "children": [{"id": "bb4775ae-2290-4d61-b92b-bb7024d62a94", "type": "subtopic", "title": "Retirement plan types", "child