  title = 'Compensation and Benefits',
  goal = 'Compensation and Benefits',
  summary = 'A rigorous undergraduate course in compensation, benefits, and total rewards for future HR professionals. Students learn to design, analyze, administer, and communicate reward systems that are competitive, equitable, legally compliant, financially responsible, and aligned with organizational strategy.',
  data = $cbenjson${"slug": "compensation-and-benefits", "title": "Compensation and Benefits", "description": "A rigorous undergraduate course in compensation, benefits, and total rewards for future HR professionals. Students learn to design, analyze, administer, and communicate reward systems that are competitive, equitable, legally compliant, financially responsible, and aligned with organizational strategy.", "topics": [{"id": "126664df-ddd3-4a4a-bd1f-c69bda6ef2e2", "type": "topic", "title": "Total Rewards Strategy and Compensation Philosophy", "description": "Students learn to treat rewards as a strategic system, not a payroll afterthought. The unit connects pay, benefits, recognition, flexibility, career growth, and employee experience to business goals and workforce values.", "children": [{"id": "7b7cd825-a647-4a9a-a355-30457953cb9f", "type": "subtopic", "title": "Total rewards model", "children": [{"id": "88257e81-cf91-4da1-af35-563e15e72ba6", "type": "concept", "title": "base pay"}, {"id": "b12122bd-0c71-4140-be0e-61d6ae48d2d6", "type": "concept", "title": "variable pay"}, {"id": "a459b08b-10eb-428e-a79f-4bd7646fd4bd", "type": "concept", "title": "benefits"}, {"id": "d8bf1621-2b4e-4cdc-89bc-f53108a1d00d", "type": "concept", "title": "recognition"}, {"id": "324f39d3-f80a-4d14-9cb4-2fb107376d5d", "type": "concept", "title": "career development"}, {"id": "fc24f874-2639-4589-8597-99966c1f25f4", "type": "concept", "title": "work-life rewards"}], "description": "This subtopic gives students the full map of financial and nonfinancial rewards so they can see how pay and benefits fit within a broader employment deal."}, {"id": "5856d069-e622-42f5-ad50-4caea1989196", "type": "subtopic", "title": "Compensation philosophy", "children": [{"id": "09bd11a9-93b2-4b18-835c-847fe2ce1851", "type": "concept", "title": "lead-lag-match strategy"}, {"id": "0c75d5d9-d609-42da-bfb2-9ba5dffe3ba9", "type": "concept", "title": "internal equity"}, {"id": "4c4b04d7-5841-47d1-9edf-5026af710458", "type": "concept", "title": "external competitiveness"}, {"id": "010faf66-7c5d-4cd7-8f98-d44fb1a16395", "type": "concept", "title": "pay for performance"}, {"id": "4c798d0a-fd16-41ee-a6e2-ca7f044826cc", "type": "concept", "title": "employee value proposition"}], "description": "Students learn how organizations make explicit choices about market position, internal equity, affordability, transparency, and performance orientation."}, {"id": "4760ce45-8891-4d4b-b996-1216d05d0d13", "type": "subtopic", "title": "Stakeholders and tradeoffs", "children": [{"id": "fa88d9a8-6849-4019-89d9-4cd47d326158", "type": "concept", "title": "employees"}, {"id": "bd17c190-d93f-491d-9a62-7d0fdac40016", "type": "concept", "title": "managers"}, {"id": "e18a7a03-bf94-4d19-8f4d-4e2aa3cffe9e", "type": "concept", "title": "finance"}, {"id": "e3b3d9b4-60d0-408d-b8f2-9bc80262da96", "type": "concept", "title": "legal and compliance"}, {"id": "48fc3059-a2f5-4d75-bd09-79aab7d7503f", "type": "concept", "title": "unions or employee voice"}, {"id": "5085d570-ed83-4dd7-9a0b-6908ec12baa3", "type": "concept", "title": "shareholders and boards"}], "description": "Students practice balancing employee needs, leadership goals, legal requirements, finance constraints, and labor-market realities."}]}, {"id": "11110791-d8aa-41fd-b718-e4687c54f534", "type": "topic", "title": "Job Analysis, Job Architecture, and Job Evaluation", "description": "This section builds the foundation for fair pay decisions: organizations must understand work before they can price, grade, compare, or defend it.", "children": [{"id": "87d3f658-6b9f-403a-b357-938e8331caa6", "type": "subtopic", "title": "Job analysis", "children": [{"id": "dc266d0a-c82d-4d55-bdb8-63ed599bbdf1", "type": "concept", "title": "task statements"}, {"id": "c20f553f-2fdf-4efd-b18c-b869d926f579", "type": "concept", "title": "knowledge, skills, and abilities"}, {"id": "64766261-ab83-4c54-a8bb-095a4d30ddc6", "type": "concept", "title": "essential functions"}, {"id": "3eb28d98-bb19-4198-9358-7a1ed0b5209e", "type": "concept", "title": "physical and mental demands"}, {"id": "4dd6efa9-7ded-40ac-8a5d-aabc1a64bcbc", "type": "concept", "title": "documentation standards"}], "description": "Students learn to document duties, responsibilities, working conditions, and required qualifications in a way that supports pay and compliance decisions."}, {"id": "4b91224c-156c-4b4e-8f20-ee510a426afb", "type": "subtopic", "title": "Job architecture", "children": [{"id": "70bb8c09-6251-4b03-b0d9-76d58f23ef6e", "type": "concept", "title": "job families"}, {"id": "2e7a1c12-7d46-4eea-9d0d-10f69f8079e7", "type": "concept", "title": "career streams"}, {"id": "a1ac66ea-240a-4109-bbd2-70a1a0927b30", "type": "concept", "title": "leveling guides"}, {"id": "8641d812-054b-401f-8cea-dd0afc27d3e6", "type": "concept", "title": "competency ladders"}, {"id": "5b629522-3b01-4cd6-bddf-51d0f3038708", "type": "concept", "title": "promotion criteria"}], "description": "The course explains how roles are organized into families, levels, career paths, and progression rules."}, {"id": "140c4993-a2f8-4b60-a5fc-e2eaa67047c2", "type": "subtopic", "title": "Job evaluation methods", "children": [{"id": "9c9d7528-8773-4d4d-980f-ba0f671a893f", "type": "concept", "title": "ranking"}, {"id": "4dea6fb3-b8fc-415b-b529-35db1890471b", "type": "concept", "title": "classification"}, {"id": "49ee9bbc-5dc2-4c20-90ae-06cfc23b4c20", "type": "concept", "title": "point-factor method"}, {"id": "365bbd10-851e-4e41-b0e9-a0455e8caeeb", "type": "concept", "title": "factor comparison"}, {"id": "41850a57-12fc-4a7d-8a25-3e307be499fb", "type": "concept", "title": "whole-job matching"}], "description": "Students compare systematic ways to judge internal job value and understand the strengths and limitations of each method."}]}, {"id": "f1296a95-b070-48d9-8994-5deffea90bb3", "type": "topic", "title": "Labor Market Pricing and Compensation Data", "description": "Students learn how organizations use external market data responsibly, including how to choose surveys, match jobs, age data, and avoid false precision.", "children": [{"id": "d8b76622-9071-4a53-8fcd-36dbfef7306d", "type": "subtopic", "title": "Compensation surveys", "children": [{"id": "d447998e-dda7-4c53-be72-21aa436faf71", "type": "concept", "title": "survey scope"}, {"id": "41a2cde7-1d87-4e69-a702-27527fea1d3e", "type": "concept", "title": "participant mix"}, {"id": "df715472-3531-47a2-ba55-2a8fd69c3419", "type": "concept", "title": "job matching"}, {"id": "9feda4d2-1f1c-4afd-a0ef-a76f221b29e4", "type": "concept", "title": "sample size"}, {"id": "e03502e1-43b7-4c63-84ba-49099e6efd64", "type": "concept", "title": "published cuts"}], "description": "This subtopic teaches students how salary surveys are built and how to judge whether data are appropriate for a specific role or labor market."}, {"id": "8f60dd2c-1b92-4ebd-b23b-d4a92540c5d5", "type": "subtopic", "title": "Market pricing workflow", "children": [{"id": "e7fc5d03-e059-4056-ab01-024c39579b73", "type": "concept", "title": "benchmark jobs"}, {"id": "f662f86a-553a-4047-a2b8-8921aaa19c0a", "type": "concept", "title": "percentiles"}, {"id": "8483d62e-a05a-4197-a150-cf01479d9919", "type": "concept", "title": "data aging"}, {"id": "225eda12-eeb0-4b90-99d6-6399550f2331", "type": "concept", "title": "geographic differentials"}, {"id": "a0dfc1bd-c4fd-41bf-b6c0-3f2ae2a36694", "type": "concept", "title": "blended market rates"}], "description": "Students practice turning raw market data into usable pay recommendations."}, {"id": "f4daaf52-dbdd-48a4-9739-92f891f2214b", "type": "subtopic", "title": "Data quality and ethics", "children": [{"id": "eed0c9db-d3e2-4970-80e8-4debc7c212c6", "type": "concept", "title": "data recency"}, {"id": "36c8461d-4c66-49a8-a6d3-45e9172aecc4", "type": "concept", "title": "outliers"}, {"id": "94b8ea5a-bce5-4856-a917-eab6a5bd6a47", "type": "concept", "title": "confidentiality"}, {"id": "a1a24ea4-2627-4f6e-8412-91fbba8982aa", "type": "concept", "title": "antitrust caution"}, {"id": "a5b57348-6a9a-4e25-aa33-1451a97927e4", "type": "concept", "title": "vendor governance"}], "description": "Students learn why compensation data can mislead and why confidentiality, antitrust boundaries, and data governance matter."}]}, {"id": "7c125c33-fa00-448d-bb6c-48138eba2ae5", "type": "topic", "title": "Base Pay Structures, Grades, and Ranges", "description": "This unit shows how organizations turn strategy, job value, and market data into structured pay systems that managers can administer consistently.", "children": [{"id": "79890eff-a439-4f3b-82ae-1878a6afb2ac", "type": "subtopic", "title": "Pay grades and bands", "children": [{"id": "deac541b-72ca-4c79-9782-67bd3b684812", "type": "concept", "title": "traditional grades"}, {"id": "12a03cd3-7636-4fa4-97ad-0d71c086cead", "type": "concept", "title": "broadbanding"}, {"id": "dd78396f-ed4b-4046-9e82-6f418e7e31fa", "type": "concept", "title": "career bands"}, {"id": "bea23620-6734-4046-9139-43e6b67bed56", "type": "concept", "title": "grade overlap"}, {"id": "58168dd4-a08d-4fbb-9ae4-993e04a8e2c4", "type": "concept", "title": "control points"}], "description": "Students learn how jobs are grouped into pay grades or broader bands and what each structure enables or constrains."}, {"id": "1012aa72-4e7f-4973-a551-9a7e172c29fa", "type": "subtopic", "title": "Range design", "children": [{"id": "3922ef3a-65a0-429b-85fd-0f4e5b10bea4", "type": "concept", "title": "range minimum"}, {"id": "2569b348-f394-4f47-814a-b872000aae7c", "type": "concept", "title": "midpoint"}, {"id": "acc91e87-4eda-4290-a2f7-5c09b1f3aa1b", "type": "concept", "title": "range maximum"}, {"id": "792f959a-2643-4d14-a04f-71181999fef3", "type": "concept", "title": "range spread"}, {"id": "8d4e089a-f771-45f4-bcb8-b6aed105315e", "type": "concept", "title": "midpoint differential"}], "description": "The class covers minimums, midpoints, maximums, spreads, and midpoint progressions."}, {"id": "e4f9e8b6-8cac-4eb5-ac36-e3fda4077cc4", "type": "subtopic", "title": "Pay administration", "children": [{"id": "b4ff0777-298f-45fd-b6f0-a832ded17eee", "type": "concept", "title": "salary offers"}, {"id": "ac4a41ce-a6ce-4a4b-bb9d-8aaf96f7d3a3", "type": "concept", "title": "merit increases"}, {"id": "fe02ccf2-8141-49af-b0be-f67c104553ae", "type": "concept", "title": "promotional increases"}, {"id": "260a8429-2df2-4be9-8d6a-f6e5a9024ed9", "type": "concept", "title": "red-circle rates"}, {"id": "eb91117d-2601-4930-bc80-056b4839b13d", "type": "concept", "title": "green-circle rates"}], "description": "Students learn the rules and routines that keep pay structures from drifting into inconsistency."}]}, {"id": "e7bea271-5d3b-4b62-83ec-0aabce0d01ba", "type": "topic", "title": "Variable Pay, Incentives, and Recognition", "description": "Students examine when variable rewards motivate performance and when they create risk, gaming, inequity, or short-term thinking.", "children": [{"id": "de188599-aec7-4eb4-b00d-5a14c87df4c5", "type": "subtopic", "title": "Incentive plan design", "children": [{"id": "b0b1ecc5-7312-42e5-ab1c-1787b1e55dee", "type": "concept", "title": "eligibility"}, {"id": "302430c8-cef9-49ba-8c28-9816e312e570", "type": "concept", "title": "performance measures"}, {"id": "c76f2e36-84bc-4be7-b2c8-f087d344ad1d", "type": "concept", "title": "threshold-target-maximum"}, {"id": "c87b8ae4-7e2c-479d-8efe-5cb019ddeb73", "type": "concept", "title": "payout curves"}, {"id": "4b91373e-779f-41e3-84ee-28932f5cf0a6", "type": "concept", "title": "plan funding"}], "description": "Students learn to connect eligibility, measures, targets, funding, and payout mechanics to desired behavior."}, {"id": "2de277dc-4039-4539-ac78-51e3a93cf4a7", "type": "subtopic", "title": "Short-term and sales incentives", "children": [{"id": "78413bb3-0048-4fed-a983-3710c9776f15", "type": "concept", "title": "individual bonus"}, {"id": "db28870b-2b90-4fc9-bd96-253589a1b190", "type": "concept", "title": "team bonus"}, {"id": "52b382eb-48f3-4f7d-ba82-4dbc7d367471", "type": "concept", "title": "profit sharing"}, {"id": "8a14683d-724c-44e5-b550-798fa9cf1645", "type": "concept", "title": "commission"}, {"id": "89c5ce3e-98b3-4aa9-9978-6d52096f8253", "type": "concept", "title": "quota and accelerators"}], "description": "The course studies common designs for annual bonuses and sales compensation."}, {"id": "071f9980-e6a0-437e-b625-27bb22f3a114", "type": "subtopic", "title": "Recognition and noncash rewards", "children": [{"id": "1ad01555-c28e-469f-93ae-7dafc22230a9", "type": "concept", "title": "spot awards"}, {"id": "67340b9a-b4c8-4720-86f0-4cbd6abd9c6e", "type": "concept", "title": "peer recognition"}, {"id": "a5919f74-ca0d-4939-8ff6-504d7d4a06dc", "type": "concept", "title": "service awards"}, {"id": "b58a1619-ea62-4027-872a-5b31a741d47d", "type": "concept", "title": "symbolic rewards"}, {"id": "8b3c5d4b-8d2d-4c47-bb14-9cfb0fdd7a1f", "type": "concept", "title": "recognition bias"}], "description": "Students learn why timely, meaningful recognition can reinforce culture when designed with equity and authenticity."}]}, {"id": "071c7a87-cac4-4ca6-afc2-872ffb3eb9cc", "type": "topic", "title": "Employee Benefits Strategy and Plan Design", "description": "This section treats benefits as both a major cost and a major source of employee security, retention, wellbeing, and equity.", "children": [{"id": "1e6e1531-5f7b-4160-b250-d210bc036066", "type": "subtopic", "title": "Benefits strategy", "children": [{"id": "b36bed05-f19a-423a-8a9b-9d18430ec0fe", "type": "concept", "title": "benefit objectives"}, {"id": "a17d152d-0968-4a6d-bf50-05194df3f978", "type": "concept", "title": "employee demographics"}, {"id": "adfceea8-2d71-419e-9506-d942fe714865", "type": "concept", "title": "cost sharing"}, {"id": "2ebab3f2-065e-440f-bc91-6d13b98c0599", "type": "concept", "title": "choice architecture"}, {"id": "f70ae2b3-cd8c-4c86-9b48-420897cca6b5", "type": "concept", "title": "communication strategy"}], "description": "Students learn how organizations choose benefits based on workforce needs, market expectations, affordability, and values."}, {"id": "69d88af9-30f1-43d2-a002-8a25ca958bd6", "type": "subtopic", "title": "Health and welfare benefits", "children": [{"id": "0c77ef89-fa83-44df-bc0d-b822ecb9f5c4", "type": "concept", "title": "medical plans"}, {"id": "e8811277-9e6f-48e6-b0ff-ea36d51f93cd", "type": "concept", "title": "dental and vision"}, {"id": "2502a67d-6cb9-47e0-85ac-7e62b8a1c9f6", "type": "concept", "title": "life insurance"}, {"id": "d3549b22-f6eb-4668-91be-1be46a6fa3db", "type": "concept", "title": "disability insurance"}, {"id": "05649e28-1a52-439c-baf1-40709cb8e73b", "type": "concept", "title": "employee assistance programs"}], "description": "The unit introduces health plans and related welfare benefits that dominate benefit budgets."}, {"id": "91a8edfe-d76a-4fdd-9ff5-18e3c51482c5", "type": "subtopic", "title": "Paid time, flexibility, and wellbeing", "children": [{"id": "bca216aa-b087-425c-9ee0-895f47c75454", "type": "concept", "title": "paid time off"}, {"id": "b06d2373-182b-40db-afbb-2642ad0be3b8", "type": "concept", "title": "sick leave"}, {"id": "dc83dec0-c94b-4848-9877-34ef0fd4690d", "type": "concept", "title": "parental leave"}, {"id": "e1f1835a-ef97-4338-b551-3b72a13e3483", "type": "concept", "title": "wellbeing programs"}, {"id": "ff0498b9-17d7-45c4-952c-c0a08a499d40", "type": "concept", "title": "flexible work"}], "description": "Students examine leave, scheduling, flexibility, and wellbeing benefits as part of total rewards."}]}, {"id": "e6ab124f-f4e4-407e-add9-da19f1239742", "type": "topic", "title": "Retirement, Financial Security, and Benefits Finance", "description": "Students learn how retirement and financial-security benefits work, why they matter, and how employers manage long-term cost and compliance obligations.", "children": [{"id": "bb4775ae-2290-4d61-b92b-bb7024d62a94", "type": "subtopic", "title": "Retirement plan types", "children": [{"id": "17bda17e-b8b5-4179-a0b8-02df388be264", "type": "concept", "title": "defined benefit plans"}, {"id": "4821330a-1a22-4f45-93ce-8664c6708c9e", "type": "concept", "title": "defined contribution plans"}, {"id": "18277031-1f26-4208-bec8-b355353a0edc", "type": "concept", "title": "401(k)"}, {"id": "09657e7c-a586-429f-ad1d-baa90d8e3438", "type": "concept", "title": "vesting"}, {"id": "75ebe621-d08c-4e89-a38b-376ace7520dc", "type": "concept", "title": "employer match"}], "description": "The course compares major retirement plan designs and the risks they allocate between employer and employee."}, {"id": "c38f7333-261c-492d-a5b0-3dff7b44d5c5", "type": "subtopic", "title": "Financial wellness", "children": [{"id": "36fe9557-3c85-4af7-a60a-d75cc4e6fb2a", "type": "concept", "title": "student loan assistance"}, {"id": "9ac5ea0e-9460-4fcf-9363-03072e14df6e", "type": "concept", "title": "emergency savings"}, {"id": "896166a1-8cfa-40b2-a88a-d34c9e1bdbdc", "type": "concept", "title": "financial coaching"}, {"id": "bcfe4342-01b4-4b6e-8d3c-e3c1e56a9944", "type": "concept", "title": "tuition assistance"}, {"id": "b761ed1c-265b-4c99-bcba-a2f7e67f67ee", "type": "concept", "title": "equity grants"}], "description": "Students examine benefits that support financial resilience beyond retirement savings."}, {"id": "0c5ed8c9-0af2-4408-8eb2-d6bf41a29c99", "type": "subtopic", "title": "Benefits finance", "children": [{"id": "b814ee1e-e53b-4eae-a8e5-d4d703753fea", "type": "concept", "title": "premium trends"}, {"id": "4d50d873-d1e6-4820-896a-24c7424806fd", "type": "concept", "title": "claims experience"}, {"id": "258e15d5-436a-466c-ae7e-84707b9af7fa", "type": "concept", "title": "employer contribution strategy"}, {"id": "c59b9b2b-b48a-4cda-8ef1-89ed74fff579", "type": "concept", "title": "stop-loss insurance"}, {"id": "12c8d07b-5b11-4726-b1b1-3f789e33c69d", "type": "concept", "title": "total benefit cost"}], "description": "Students learn the basic cost drivers and budgeting questions behind benefit decisions."}]}, {"id": "8f5da693-22bd-4644-90d1-290298671611", "type": "topic", "title": "Executive Compensation and Governance", "description": "This unit introduces executive pay as a specialized area where incentives, governance, disclosure, fairness, and public legitimacy collide.", "children": [{"id": "68cee092-1d39-4ed6-90f4-a6fc136a832d", "type": "subtopic", "title": "Executive pay components", "children": [{"id": "aa984a31-4b34-4f57-8f2d-7c6f6e3f2b4a", "type": "concept", "title": "base salary"}, {"id": "e9862af6-8ccc-4540-8502-053a0894abcb", "type": "concept", "title": "annual incentives"}, {"id": "b8bcb24d-490b-439a-84d0-7b7c216cebd4", "type": "concept", "title": "long-term incentives"}, {"id": "eccca6b7-1da3-4429-8378-590cc3ddc82d", "type": "concept", "title": "equity awards"}, {"id": "66da5bde-3b9d-4bc1-9c92-977e71599b22", "type": "concept", "title": "perquisites"}], "description": "Students learn the common building blocks of executive compensation and why each exists."}, {"id": "d715bbac-39a8-4e50-9cdf-b4610dc35f66", "type": "subtopic", "title": "Governance and oversight", "children": [{"id": "f19825c8-8c77-4658-b628-b088a2189b98", "type": "concept", "title": "compensation committee"}, {"id": "5287ed87-b3d7-4751-880b-e88fc0fd370f", "type": "concept", "title": "say-on-pay"}, {"id": "d6e31061-3595-4f7b-acb6-8a2f127052d6", "type": "concept", "title": "peer groups"}, {"id": "3df1dd22-cf6d-4ba1-91a9-220c9cb943b7", "type": "concept", "title": "proxy disclosure"}, {"id": "33dda4a3-8247-4699-a7a7-5c6300acf6a3", "type": "concept", "title": "consultant independence"}], "description": "The class explains the roles of boards, compensation committees, consultants, and disclosure rules."}, {"id": "f7bfe5e5-db59-4e7f-8b46-758c0090066d", "type": "subtopic", "title": "Risk and fairness debates", "children": [{"id": "336b66b5-3ae9-4ba1-816d-b51a08e4f2eb", "type": "concept", "title": "pay-performance alignment"}, {"id": "5e12a94a-dc68-4aa2-9649-56